import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.B9unkguw.js";const g=JSON.parse('{"title":"Missing Actuators Page (PX4)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-user-guide/troubleshooting/actuators.md","filePath":"zh/qgc-user-guide/troubleshooting/actuators.md"}'),n={name:"zh/qgc-user-guide/troubleshooting/actuators.md"};function d(r,e,s,c,l,h){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="missing-actuators-page-px4" tabindex="-1">Missing Actuators Page (PX4) <a class="header-anchor" href="#missing-actuators-page-px4" aria-label="Permalink to &quot;Missing Actuators Page (PX4)&quot;">​</a></h1><p>The <a href="./../setup_view/px4/actuators.html">Actuators page</a> is shown when QGroundControl receives and initializes the vehicle&#39;s <code>COMP_METADATA_TYPE_ACTUATORS</code> component metadata. The firmware version alone does not determine whether the page is available. If the metadata is unavailable, cannot be initialized, or its top-level <code>show-ui-if</code> condition evaluates to false, QGroundControl uses the legacy Motors page instead.</p><h2 id="capture-diagnostic-logs" tabindex="-1">Capture Diagnostic Logs <a class="header-anchor" href="#capture-diagnostic-logs" aria-label="Permalink to &quot;Capture Diagnostic Logs&quot;">​</a></h2><ol><li>Open <strong>Application Settings &gt; App Log Viewer</strong>.</li><li>Click <strong>Categories</strong> and enable these categories: <ul><li><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></li><li><code>Vehicle.Actuators.Common</code></li><li><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></li><li><code>Vehicle.FTPManager</code></li></ul></li><li>Connect the vehicle. If it is already connected, disconnect and reconnect it so that QGroundControl requests the component metadata again.</li><li>Open <strong>Vehicle Setup</strong> and check whether <strong>Actuators</strong> or <strong>Motors</strong> is available.</li><li>Return to <strong>App Log Viewer</strong> and click <strong>Save</strong>. Keep the saved app log unchanged when attaching it to a support request.</li></ol><p>The metadata URI can use MAVLink FTP (<code>mavlinkftp://</code>) or HTTP. QGroundControl tries the primary URI first and then the fallback URI advertised by the vehicle.</p><h2 id="read-the-diagnostic-messages" tabindex="-1">Read the Diagnostic Messages <a class="header-anchor" href="#read-the-diagnostic-messages" aria-label="Permalink to &quot;Read the Diagnostic Messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Log category</th><th>Message or pattern</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Vehicle did not provide actuators metadata via component information</code></td><td>No actuator metadata was received from the vehicle.</td></tr><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Actuators initialization failed</code></td><td>Metadata was received but could not be parsed or initialized.</td></tr><tr><td><code>Vehicle.Actuators.PX4AutoPilotPlugin</code></td><td><code>Condition &#39;show-ui-if&#39; evaluated to false</code></td><td>The vehicle&#39;s metadata indicated the page should not be shown. This can be intentional for your configuration, or a firmware/metadata mismatch. Attach the saved log to a support request.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>primary failed, requesting metadata (fallback) from ...</code></td><td>The primary metadata URI failed and QGroundControl is trying the fallback URI.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>FTP download failed</code> or <code>HTTP download failed</code></td><td>The selected transport could not download the metadata. An HTTP status such as <code>404</code> identifies a missing or incorrect URL.</td></tr><tr><td><code>ComponentInformation.RequestMetaDataTypeStateMachine</code></td><td><code>failed to load metadata (primary and fallback)</code></td><td>Both metadata URIs failed, so the Actuators page cannot be initialized.</td></tr><tr><td><code>Vehicle.FTPManager</code></td><td><code>Download fromCompId</code>, <code>Nak - ...</code>, or timeout messages</td><td>Details of the MAVLink FTP request and any vehicle-side error.</td></tr></tbody></table><h2 id="include-this-information-in-a-support-request" tabindex="-1">Include This Information in a Support Request <a class="header-anchor" href="#include-this-information-in-a-support-request" aria-label="Permalink to &quot;Include This Information in a Support Request&quot;">​</a></h2><p>Include the QGroundControl version and build, PX4 firmware version, vehicle type, connection type, whether the legacy Motors page appears, and the saved app log. If the log contains a fallback or download error, include the full line with the URI and error text. Also mention whether reconnecting the vehicle changes the result.</p>',9)]))}const p=t(n,[["render",d]]);export{g as __pageData,p as default};
